mapper.select:
SELECT latest.frame_id
FROM (
    SELECT frame_id
    FROM sensor_frame
    WHERE panel_id = #{panelId}
    ORDER BY frame_id DESC
    LIMIT #{sampleSize}
) latest
ORDER BY latest.frame_id ASC

SELECT sfc.current_a AS am, sfc.arc_counter AS `count` FROM sensor_frame_circuit sfc WHERE sfc.circuit_id = #{circuitId} AND sfc.frame_id IN
#{frameId}
ORDER BY sfc.frame_id ASC

SELECT volt_v AS voltage, leak_ma AS leakage_current, temperature AS temperature, humidity AS humidity, fire_raw AS fire_raw, gas_raw AS gas_raw, door_status AS door_open, total_current AS total_current, total_power AS total_power FROM sensor_frame WHERE panel_id = #{panelId} AND frame_id IN
#{frameId}
ORDER BY frame_id ASC

SELECT MAX(sfc.frame_id)
FROM sensor_frame_circuit sfc
WHERE sfc.circuit_id = #{circuitId}

SELECT COUNT(*)
FROM ai_diagnosis_result
WHERE circuit_id = #{circuitId}

SELECT COUNT(*)
FROM ai_diagnosis_result ai
INNER JOIN circuit c ON c.circuit_id = ai.circuit_id
WHERE c.panel_id = #{panelId}
  AND c.deleted_at IS NULL
  AND ai.diagnosed_at >= #{fromAt}

    AND ai.verdict = #{verdict}

SELECT ai.result_id, ai.circuit_id, c.channel_no, ai.verdict, ai.confidence, ai.n_samples, ai.warning, ai.trigger_type, ai.diagnosed_at, ai.risk_level, ai.risk_score, ai.anomaly, ai.anomaly_score, ai.predicted_current FROM ai_diagnosis_result ai INNER JOIN circuit c ON c.circuit_id = ai.circuit_id WHERE c.panel_id = #{panelId} AND c.deleted_at IS NULL AND ai.diagnosed_at >= #{fromAt}
AND ai.verdict = #{verdict}
ORDER BY ai.diagnosed_at DESC, ai.result_id DESC LIMIT #{limit}
